machine_start_gcode:
; Model: Snapmaker A350
; Update: 20250313
; Printer : [printer_preset]
; Profile : [print_preset]
; Plate   : [plate_name]

; SM2_PURGE plan (PR-09): purge beside the first-layer footprint (front, else left, else right; never behind it, kit/Dual
; exclude areas are back strips), passes 15/10 mm from it, X 10 mm inside the bed; old X40 Y0 line if no side has room.
{local sm2_mvs = filament_max_volumetric_speed[initial_extruder]; local sm2_fil_area = 0.785398 * filament_diameter[initial_extruder] * filament_diameter[initial_extruder]}
{local sm2_purge_w = 1.25 * nozzle_diameter[initial_extruder]; local sm2_purge_epm = sm2_purge_w * 0.3 / sm2_fil_area}
{local sm2_purge_f = sm2_mvs > 0 ? min(3420.0, 60.0 * sm2_mvs / (sm2_purge_w * 0.3)) : 3420.0; local sm2_prime_f = sm2_mvs > 0 ? 60.0 * sm2_mvs / sm2_fil_area : 200.0}
{local sm2_purge_off = 15.0; local sm2_bx0 = print_bed_min[0] + 10.0; local sm2_bx1 = print_bed_max[0] - 10.0; local sm2_by0 = print_bed_min[1]}
{local sm2_front = first_layer_print_min[1] - sm2_purge_off >= sm2_by0; local sm2_left = first_layer_print_min[0] - sm2_purge_off >= sm2_bx0; local sm2_right = first_layer_print_max[0] + sm2_purge_off <= sm2_bx1}
{local sm2_purge_side = sm2_front ? "front" : sm2_left ? "left" : sm2_right ? "right" : "fallback"; local sm2_purge_alongx = sm2_front || !(sm2_left || sm2_right)}
{local sm2_purge_len = sm2_purge_side == "fallback" ? 180.0 : 100.0; local sm2_purge_step = sm2_purge_side == "fallback" ? 10.0 : 5.0}
{local sm2_purge_x = sm2_front ? max(sm2_bx0, min(first_layer_print_min[0], sm2_bx1 - sm2_purge_len)) : sm2_left ? first_layer_print_min[0] - sm2_purge_off : sm2_right ? first_layer_print_max[0] + sm2_purge_off : print_bed_min[0] + 40.0}
{local sm2_purge_y = sm2_front ? first_layer_print_min[1] - sm2_purge_off : sm2_left || sm2_right ? max(sm2_by0, min(first_layer_print_min[1], first_layer_print_max[1] - sm2_purge_len)) : sm2_by0}
{local sm2_purge_ex = sm2_purge_x + (sm2_purge_alongx ? sm2_purge_len : 0.0); local sm2_purge_ey = sm2_purge_y + (sm2_purge_alongx ? 0.0 : sm2_purge_len)}
{local sm2_purge_sx = sm2_purge_side == "left" ? sm2_purge_step : sm2_purge_side == "right" ? 0.0 - sm2_purge_step : 0.0; local sm2_purge_sy = sm2_purge_alongx ? sm2_purge_step : 0.0}
; SM2_PARK plan: the flush wait and the E4 blob happen 10 mm behind the purge start and 10 mm further from the part
; (fallback: the old X10 Y0), X kept 10 mm inside the bed, Y >= bed min; if the clamps leave the blob < 10 mm from
; the purge start it goes 10 mm beyond the first pass end instead. After the blob: slow lift with the fan on, no wipe.
{local sm2_park_d = 10.0; local sm2_park_back = sm2_purge_side == "fallback" ? 30.0 : sm2_park_d; local sm2_purge_ax = sm2_purge_alongx ? 1.0 : 0.0; local sm2_purge_ay = 1.0 - sm2_purge_ax}
{local sm2_park_ox = sm2_purge_sx > 0 ? 0.0 - sm2_park_d : sm2_purge_sx < 0 ? sm2_park_d : 0.0; local sm2_park_oy = sm2_purge_sy > 0 ? 0.0 - sm2_park_d : 0.0}
{local sm2_park_x1 = max(sm2_bx0, min(sm2_bx1, sm2_purge_x + sm2_park_ox - sm2_park_back * sm2_purge_ax)); local sm2_park_y1 = max(sm2_by0, sm2_purge_y + sm2_park_oy - sm2_park_back * sm2_purge_ay)}
{local sm2_park_dx = sm2_park_x1 - sm2_purge_x; local sm2_park_dy = sm2_park_y1 - sm2_purge_y; local sm2_park_at_end = sm2_park_dx * sm2_park_dx + sm2_park_dy * sm2_park_dy < sm2_park_d * sm2_park_d - 0.01}
{local sm2_park_x = sm2_park_at_end ? max(sm2_bx0, min(sm2_bx1, sm2_purge_ex + sm2_park_ox + sm2_park_d * sm2_purge_ax)) : sm2_park_x1; local sm2_park_y = sm2_park_at_end ? max(sm2_by0, sm2_purge_ey + sm2_park_oy + sm2_park_d * sm2_purge_ay) : sm2_park_y1}
; SM2_PURGE {sm2_purge_side} start X{digits(sm2_purge_x, 0, 2)} Y{digits(sm2_purge_y, 0, 2)} len {sm2_purge_len} width {digits(sm2_purge_w, 0, 3)} F{digits(sm2_purge_f, 0, 0)} footprint X{digits(first_layer_print_min[0], 0, 1)}-{digits(first_layer_print_max[0], 0, 1)} Y{digits(first_layer_print_min[1], 0, 1)}-{digits(first_layer_print_max[1], 0, 1)}
; SM2_PARK {sm2_park_at_end ? "end" : "start"} X{digits(sm2_park_x, 0, 2)} Y{digits(sm2_park_y, 0, 2)} flush wait and blob here, then lift and travel to the purge start
T[initial_extruder]

M140 S{first_layer_bed_temperature[initial_extruder]}

; you can clean the nozzle
M104 S165
M204 S100
G28
;G0 Z216 F960.0
;G0 Y175.0 F3420.0
;G0 X160.0

M190 R{first_layer_bed_temperature[initial_extruder]}
; SM2_MESH saved bed mesh active since G28 (no G29/M420 needed), bed at temperature: slot for an adaptive G1029 region probe (PR-23)
{if printer_notes=~/.*SM2_ADAPTIVE_MESH.*/}; SM2_MESH_ADAPTIVE on (printer notes contain SM2_ADAPTIVE_MESH): G1029 A re-homes and re-probes the saved grid points under the first layer, not saved, no H (bed already hot); needs controller SM2-5.2.1-a250t.8+, older firmware probes the whole grid and waits for the card step
G1029 A L{digits(max(print_bed_min[0], min(print_bed_max[0], adaptive_bed_mesh_min[0])), 0, 2)} R{digits(max(print_bed_min[0], min(print_bed_max[0], adaptive_bed_mesh_max[0])), 0, 2)} F{digits(max(print_bed_min[1], min(print_bed_max[1], adaptive_bed_mesh_min[1])), 0, 2)} B{digits(max(print_bed_min[1], min(print_bed_max[1], adaptive_bed_mesh_max[1])), 0, 2)}
{endif}
;G28
;{if 1==1}
;  G0 X0
;  G0 Z0.2 F960.0
;  G0 Y0 F3420.0
;  G0 X320
;  G0 Y350
;  G0 X0
;  G0 Y0
;{endif}

M83

; flush initial nozzle
T[initial_extruder]
; flush T[initial_extruder] {filament_type[(initial_extruder % 2 == 0 ? min(initial_extruder + initial_extruder, 63) : max(initial_extruder - (1-initial_extruder), 0))]} capped at range_high {nozzle_temperature_range_high[(initial_extruder % 2 == 0 ? min(initial_extruder + initial_extruder, 63) : max(initial_extruder - (1-initial_extruder), 0))]} and head max 275
M104 S{min(275, min(nozzle_temperature_range_high[(initial_extruder % 2 == 0 ? min(initial_extruder + initial_extruder, 63) : max(initial_extruder - (1-initial_extruder), 0))], max(250, nozzle_temperature_initial_layer[(initial_extruder % 2 == 0 ? min(initial_extruder + initial_extruder, 63) : max(initial_extruder - (1-initial_extruder), 0))] + 15)))}; common flush temp

G0 X{digits(sm2_park_x, 0, 2)} Y{digits(sm2_park_y, 0, 2)} F3420.0
{if max(first_layer_bed_temperature[initial_extruder], bed_temperature[initial_extruder]) >= 90}
; SM2_HOTBED_COMP +0.06 bed={first_layer_bed_temperature[initial_extruder]}
G0 Z1.66 F960.0
G92 Z1.6 ;+0.06 hot-bed comp, applied away from the bed
{else}
G0 Z1.6 F960.0
{endif}

M109 S{min(275, min(nozzle_temperature_range_high[(initial_extruder % 2 == 0 ? min(initial_extruder + initial_extruder, 63) : max(initial_extruder - (1-initial_extruder), 0))], max(250, nozzle_temperature_initial_layer[(initial_extruder % 2 == 0 ? min(initial_extruder + initial_extruder, 63) : max(initial_extruder - (1-initial_extruder), 0))] + 15)))} C2 W1

G1 Z0.4 F200
G1 E4 F{digits(min(80.0, sm2_prime_f), 0, 1)}
G92 E0

M106 S{min(255, (fan_max_speed[(initial_extruder % 2 == 0 ? min(initial_extruder + initial_extruder, 63) : max(initial_extruder - (1-initial_extruder), 0))] + 10) * 2.55)}

M104 S{nozzle_temperature_initial_layer[(initial_extruder % 2 == 0 ? min(initial_extruder + initial_extruder, 63) : max(initial_extruder - (1-initial_extruder), 0))] + 5}

G0 Z5.6 F200
M107

G0 X{digits(sm2_purge_x, 0, 2)} Y{digits(sm2_purge_y, 0, 2)} F3420.0
G0 Z0.3 F960.0
M109 S{nozzle_temperature_initial_layer[(initial_extruder % 2 == 0 ? min(initial_extruder + initial_extruder, 63) : max(initial_extruder - (1-initial_extruder), 0))]} C3 W1
G1 E3 F{digits(min(200.0, sm2_prime_f), 0, 1)}
G92 E0
G1 X{digits(sm2_purge_ex, 0, 2)} Y{digits(sm2_purge_ey, 0, 2)} E{digits(sm2_purge_len * sm2_purge_epm, 0, 4)} F{digits(sm2_purge_f, 0, 0)}
G92 E0
G1 X{digits(sm2_purge_ex + sm2_purge_sx, 0, 2)} Y{digits(sm2_purge_ey + sm2_purge_sy, 0, 2)} E{digits(sm2_purge_step * sm2_purge_epm, 0, 4)} F200
G1 X{digits(sm2_purge_x + sm2_purge_sx, 0, 2)} Y{digits(sm2_purge_y + sm2_purge_sy, 0, 2)} E{digits(sm2_purge_len * sm2_purge_epm, 0, 4)} F{digits(sm2_purge_f, 0, 0)}

G1 E-{retraction_length[initial_extruder]} F200
G92 E0
G0 X{digits(sm2_purge_x + 2 * sm2_purge_sx, 0, 2)} Y{digits(sm2_purge_y + 2 * sm2_purge_sy, 0, 2)} F3420.0

; ready [plate_name]
